static inline int read_data(spng_ctx *ctx, size_t bytes)
{
    if(ctx == NULL) return 1;
    if(!bytes) return 0;

    if(ctx->streaming && (bytes > ctx->data_size))
    {
        void *buf = spng__realloc(ctx, ctx->data, bytes);
        if(buf == NULL) return SPNG_EMEM;
        ctx->data = buf;
        ctx->data_size = bytes;
