    int ret;
    ret = ctx->read_fn(ctx, ctx->read_user_ptr, ctx->data, bytes);
    if(ret) return ret;

    ctx->bytes_read += bytes;
    if(ctx->bytes_read < bytes) return SPNG_EOVERFLOW;

    return 0;
}
```

